import json
with open('src/data/seed.json') as f:
    data = json.load(f)

vehicles = data['vehicles']
print(f'Total vehicles: {len(vehicles)}')
print()

# Find all Low confidence fields
print('=== LOW CONFIDENCE FIELDS ===')
for v in vehicles:
    low_fields = []
    for k, val in v.items():
        if isinstance(val, dict) and val.get('confidence') == 'Low':
            low_fields.append(k)
    if low_fields:
        print(f'{v.get(\"make\",\"?\")} {v.get(\"model\",\"?\")} ({v.get(\"year\",\"?\")}): {low_fields}')

print()
print('=== MEDIUM CONFIDENCE (vehicle-level summary) ===')
for v in vehicles:
    med_fields = []
    for k, val in v.items():
        if isinstance(val, dict) and val.get('confidence') == 'Medium':
            med_fields.append(k)
    if med_fields:
        print(f'{v.get(\"make\",\"?\")} {v.get(\"model\",\"?\")} ({v.get(\"year\",\"?\")}): {len(med_fields)} medium ({med_fields[:3]}...)')
